package com.thangit.boardinghouse.service.integration;

import static com.thangit.boardinghouse.service.integration.IntegrationCenter.*;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;

@Service
public class ZaloOAuth {
    final JdbcClient db;final IntegrationCenter center;final IntegrationVault vault;final ZaloNotificationProvider zalo;final JsonMapper json;final TransactionTemplate tx;
    final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    public ZaloOAuth(JdbcClient db,IntegrationCenter center,IntegrationVault vault,ZaloNotificationProvider zalo,JsonMapper json,org.springframework.transaction.PlatformTransactionManager manager){this.db=db;this.center=center;this.vault=vault;this.zalo=zalo;this.json=json;tx=new TransactionTemplate(manager);}
    static String random(){byte[] data=new byte[32];new SecureRandom().nextBytes(data);return Base64.getUrlEncoder().withoutPadding().encodeToString(data);}
    static String challenge(String verifier){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}}
    public Object start(AuthenticatedUser actor){long owner=center.owner(actor);var c=center.config(owner,"ZALO");if(!vault.writable()||c.text("appId").isBlank()||c.text("oaId").isBlank()||vault.read(owner,"ZALO","APP_SECRET").isBlank())throw invalid("ZALO_OAUTH_CONFIGURATION_REQUIRED");URI redirect;try{redirect=URI.create(c.text("redirectUri"));}catch(Exception e){throw invalid("ZALO_OAUTH_REDIRECT_INVALID");}if(!"https".equals(redirect.getScheme())||!redirect.getPath().equals("/api/integrations/zalo/oauth/callback")||redirect.getQuery()!=null||redirect.getUserInfo()!=null)throw invalid("ZALO_OAUTH_HTTPS_CALLBACK_REQUIRED");String state=random(),hash=WebPushSender.hash(state),verifier=random();db.sql("INSERT INTO integration_oauth_states(state_hash,owner_id,verifier_ciphertext,expires_at) VALUES(:hash,:owner,:verifier,:expires)").param("hash",hash).param("owner",owner).param("verifier",vault.encrypt("OAUTH:"+hash,verifier)).param("expires",LocalDateTime.ofInstant(Instant.now().plusSeconds(600),ZoneOffset.UTC)).update();return Map.of("url","https://oauth.zaloapp.com/v4/oa/permission?app_id="+ZaloNotificationProvider.encode(c.text("appId"))+"&redirect_uri="+ZaloNotificationProvider.encode(c.text("redirectUri"))+"&state="+state+"&code_challenge="+challenge(verifier)+"&code_challenge_method=S256");}
    public Object callback(String state,String code){if(state==null||!state.matches("[A-Za-z0-9_-]{40,100}")||code==null||code.length()>2000)throw invalid("ZALO_OAUTH_CALLBACK_INVALID");String hash=WebPushSender.hash(state);var rows=db.sql("SELECT * FROM integration_oauth_states WHERE state_hash=:hash AND consumed_at IS NULL").param("hash",hash).query().listOfRows();if(rows.isEmpty())throw invalid("ZALO_OAUTH_STATE_REJECTED");var row=rows.getFirst();LocalDateTime expiry=row.get("expires_at") instanceof java.sql.Timestamp date?date.toLocalDateTime():LocalDateTime.parse(row.get("expires_at").toString().replace(' ','T'));if(expiry.isBefore(LocalDateTime.ofInstant(Instant.now(),ZoneOffset.UTC)))throw invalid("ZALO_OAUTH_STATE_EXPIRED");if(db.sql("UPDATE integration_oauth_states SET consumed_at=:now WHERE state_hash=:hash AND consumed_at IS NULL").param("now",LocalDateTime.ofInstant(Instant.now(),ZoneOffset.UTC)).param("hash",hash).update()!=1)throw invalid("ZALO_OAUTH_STATE_REUSED");long owner=((Number)row.get("owner_id")).longValue();var c=center.config(owner,"ZALO");String verifier=vault.decrypt("OAUTH:"+hash,row.get("verifier_ciphertext").toString());try{String body="app_id="+ZaloNotificationProvider.encode(c.text("appId"))+"&grant_type=authorization_code&code="+ZaloNotificationProvider.encode(code)+"&code_verifier="+ZaloNotificationProvider.encode(verifier);var response=http.send(HttpRequest.newBuilder(URI.create("https://oauth.zaloapp.com/v4/oa/access_token")).timeout(Duration.ofSeconds(8)).header("secret_key",vault.read(owner,"ZALO","APP_SECRET")).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());var data=json.readTree(response.body());String access=data.path("access_token").asText(),refresh=data.path("refresh_token").asText();if(response.statusCode()!=200||access.isBlank()||refresh.isBlank())throw invalid("ZALO_OAUTH_EXCHANGE_REJECTED");zalo.identity(c,access);tx.executeWithoutResult(status->{db.sql("SELECT id FROM users WHERE id=:id FOR UPDATE").param("id",owner).query(Long.class).single();vault.write(owner,"ZALO","ACCESS_TOKEN",access);vault.write(owner,"ZALO","REFRESH_TOKEN",refresh);db.sql("UPDATE integration_configs SET status='CONFIGURED',last_checked_at=NULL,result_code='ZALO_OAUTH_GRANTED',version=version+1 WHERE owner_id=:owner AND kind='ZALO'").param("owner",owner).update();});return Map.of("status","CONFIGURED","resultCode","ZALO_OAUTH_GRANTED_RUN_CAPABILITY_CHECK");}catch(Exception e){throw invalid("ZALO_OAUTH_EXCHANGE_FAILED_RECONNECT");}}
    @org.springframework.transaction.annotation.Transactional public Object webhook(long owner,String body,String signature){if(body.length()>65536)throw invalid("ZALO_WEBHOOK_TOO_LARGE");var c=center.config(owner,"ZALO");String secret=vault.read(owner,"ZALO","OA_SECRET");if(secret.isBlank()||signature==null)throw invalid("ZALO_WEBHOOK_SIGNATURE_REQUIRED");try{var data=json.readTree(body);String app=data.path("app_id").asText(),oa=data.path("oa_id").asText(data.path("sender").path("id").asText()),timestamp=data.path("timestamp").asText();if(!c.text("appId").equals(app)||!c.text("oaId").equals(oa)||Math.abs(Instant.now().toEpochMilli()-Long.parseLong(timestamp))>Duration.ofHours(24).toMillis())throw invalid("ZALO_WEBHOOK_SCOPE_OR_TIME_REJECTED");String expected=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((app+body+timestamp+secret).getBytes(StandardCharsets.UTF_8)));if(!GatewayPayments.equal(signature.startsWith("mac=")?signature.substring(4):signature,expected))throw invalid("ZALO_WEBHOOK_SIGNATURE_REJECTED");String event=data.path("event_name").asText();String key=WebPushSender.hash(body);int inserted=db.sql("INSERT IGNORE INTO integration_operations(owner_id,kind,operation,request_key,status,result_code,actor_id,finished_at) VALUES(:owner,'ZALO','WEBHOOK',:key,'CONNECTED','ZALO_WEBHOOK_VERIFIED',:owner,CURRENT_TIMESTAMP(6))").param("owner",owner).param("key",key).update();if(inserted==1&&event.equals("user_received_message")){String reference=data.path("message").path("msg_id").asText();if(ZaloNotificationProvider.safeReference(reference)!=null)db.sql("UPDATE communication_deliveries d JOIN properties p ON p.id=d.property_id SET d.status='DELIVERED',d.result_code='ZALO_DELIVERY_CONFIRMED' WHERE p.owner_id=:owner AND d.channel='ZALO' AND d.status='SENT' AND d.provider_reference=:reference").param("owner",owner).param("reference",reference).update();}return Map.of("status",inserted==1?"VERIFIED":"DUPLICATE");}catch(com.thangit.boardinghouse.common.exception.AuthException e){throw e;}catch(Exception e){throw invalid("ZALO_WEBHOOK_REJECTED");}}
}
